set local role mcp_import;
select set_config('request.jwt.claims','{"sub":"16830000-0000-0000-0000-000000000001","role":"mcp_import","exp":4102444800,"client_id":"16830000-0000-0000-0000-000000000003","session_id":"16830000-0000-0000-0000-000000000005"}',true);
